// Column helpers shared by the schema files. Column names come from the keys
// (snake_case casing in drizzle.config.ts and createDatabase).

import { type SQL, sql } from "drizzle-orm";
import { type AnyPgColumn, timestamp, uuid } from "drizzle-orm/pg-core";

export const tz = { withTimezone: true } as const;

/** UUIDv7 primary key (ADR 0020), generated by PostgreSQL 18 unless the application supplies it. */
export const id = () =>
  uuid()
    .primaryKey()
    .default(sql`uuidv7()`);

export const timestamps = {
  createdAt: timestamp(tz).notNull().defaultNow(),
  updatedAt: timestamp(tz).notNull().defaultNow(),
};

/** Validity period of a relationship; ending it sets validTo, rows are never deleted. */
export const validity = {
  validFrom: timestamp(tz).notNull().defaultNow(),
  validTo: timestamp(tz),
};

/** CHECK (column IN (...)) for a text column holding one of a fixed list. */
export function oneOf(column: AnyPgColumn, values: readonly string[]): SQL {
  return sql`${column} IN (${sql.join(
    values.map((v) => sql.raw(`'${v.replace(/'/g, "''")}'`)),
    sql`, `,
  )})`;
}

/** CHECK (array column <@ ARRAY[...]) for a text[] column holding values from a fixed list. */
export function subsetOf(column: AnyPgColumn, values: readonly string[]): SQL {
  return sql`${column} <@ ARRAY[${sql.join(
    values.map((v) => sql.raw(`'${v.replace(/'/g, "''")}'`)),
    sql`, `,
  )}]::text[]`;
}

export const validPeriod = (from: AnyPgColumn, to: AnyPgColumn): SQL =>
  sql`${to} IS NULL OR ${to} > ${from}`;
